//! 显式研究任务入口。只读取冻结本地输入；调用本模块才执行账户模拟与产物写入。
use std::{collections::{BTreeMap,BTreeSet},path::{Path,PathBuf},fs};
use rust_decimal::Decimal;
use crate::indexed_json::{Value,json};
use sha2::{Digest,Sha256};
use crate::{analysis::{baseline::{self,Signal,StructureConfig},profiles::{self,ExecutionParameters,StrategyProfile},analyzer::AnalyzerConfig,
    system::{self,SystemConfig},trading::{RuleCandle,config::TradingDayConfig}},
    data::{exchange::{self},tdx::fingerprint,security_master::SecurityMaster},
    execution::{BacktestSession,StrategyBacktest}};
use super::{AnalyticsResult,number,dec,float,date,quality,research,holding_drawdown,evidence_statistics,notion,system_research,metrics};
#[derive(Debug,Clone,Default)]
pub struct RunnerSources{pub security_master:Option<PathBuf>,pub calendar:Option<PathBuf>}
pub(crate) struct Inputs{pub(crate) grouped:BTreeMap<String,Vec<RuleCandle>>,pub(crate) sessions:Vec<BacktestSession>,pub(crate) metadata:Value,pub(crate) first:String,pub(crate) last:String,pub(crate) provenance:Value}
fn read_json(path:&Path)->AnalyticsResult<Value>{if fs::metadata(path).map_err(|e|e.to_string())?.len()>64*1024*1024{return Err("JSON input exceeds bound".into());}let bytes=fs::read(path).map_err(|e|e.to_string())?;crate::indexed_json::from_slice(bytes.strip_prefix(&[239,187,191]).unwrap_or(&bytes)).map_err(|e|e.to_string())}
pub(crate) fn parameters(value:&Value)->AnalyticsResult<ExecutionParameters>{let value=if value.is_null(){json!({})}else{value.clone()};let p:ExecutionParameters=crate::indexed_json::from_value(value).map_err(|e|e.to_string())?;p.validate()?;Ok(p)}
fn prepare_output(output:&Path)->AnalyticsResult<()>{fs::create_dir_all(output).map_err(|e|e.to_string())?;for entry in fs::read_dir(output).map_err(|e|e.to_string())?{if entry.map_err(|e|e.to_string())?.file_name()!="test_log.txt"{return Err("nonempty output; use a new directory to preserve historical experiments".into());}}Ok(())}
fn safe_name(name:&str)->AnalyticsResult<()>{if name.is_empty()||name.len()>128||!name.bytes().all(|c|c.is_ascii_alphanumeric()||matches!(c,b'_'|b'-')){return Err("unsafe research variant name".into());}Ok(())}
fn source_hashes()->Value{let files=[("analytics/runner.rs",include_str!("runner.rs")),("analysis/baseline.rs",include_str!("../analysis/baseline.rs")),("analysis/system.rs",include_str!("../analysis/system.rs")),("analysis/analyzer.rs",include_str!("../analysis/analyzer.rs")),("execution/strategy_backtest.rs",include_str!("../execution/strategy_backtest.rs"))];json!(files.into_iter().map(|(name,body)|(name,format!("{:x}",Sha256::digest(body.as_bytes())))).collect::<BTreeMap<_,_>>())}
pub(crate) fn inputs(path:&Path,required_metadata:bool,sources:&RunnerSources)->AnalyticsResult<Inputs>{
    let imported=exchange::load_bars(path).map_err(|e|e.to_string())?;let metadata_path=path.with_extension("metadata.json");let mut metadata=if metadata_path.exists(){read_json(&metadata_path)?}else if required_metadata{return Err("data provenance metadata required".into());}else{json!({})};
    if !metadata.is_object(){return Err("data metadata must be an object".into());}if required_metadata&&metadata["sha256"].as_str()!=Some(imported.source_version.as_str()){return Err("data provenance SHA-256 required and must match".into());}if metadata.get("sha256").is_some_and(|v|v.as_str()!=Some(imported.source_version.as_str())){return Err("dataset SHA-256 differs from provenance metadata".into());}
    let value=|v:f64|v.to_string().parse::<Decimal>().map_err(|_|"invalid bar decimal".to_string());let mut grouped=BTreeMap::new();let mut sessions=Vec::new();
    for(symbol,bars)in imported.bars{if bars.windows(2).any(|p|date(&p[0].timestamp)==date(&p[1].timestamp)){return Err("research requires daily bars".into());}let mut rows=Vec::new();for mut bar in bars{bar.timestamp=date(&bar.timestamp).to_owned();rows.push(RuleCandle{symbol:bar.symbol.clone(),timestamp:bar.timestamp.clone(),open:value(bar.open)?,high:value(bar.high)?,low:value(bar.low)?,close:value(bar.close)?,volume:value(bar.volume)?,adjustment_factor:value(bar.adjustment_factor)?,raw_is_st:bar.raw_is_st,raw_trading_active:bar.raw_trading_active});sessions.push(BacktestSession{daily:bar.into(),source:"frozen_local_csv".into(),data_version:imported.source_version.clone(),minutes:None,minute_source:None,minute_data_version:None});}grouped.insert(symbol,rows);}
    let first=grouped.values().filter_map(|v|v.first().map(|b|b.timestamp.clone())).min().ok_or("empty research input")?;let last=grouped.values().filter_map(|v|v.last().map(|b|b.timestamp.clone())).min().ok_or("empty research input")?;
    metadata["path"]=json!(path.canonicalize().map_err(|e|e.to_string())?.to_string_lossy());metadata["sha256"]=json!(imported.source_version);metadata["start"]=json!(first);metadata["end"]=json!(last);metadata["rows"]=json!(grouped.values().map(Vec::len).sum::<usize>());metadata["symbols"]=json!(grouped.keys().collect::<Vec<_>>());
    let mut provenance=json!({"security_master":null,"calendar":null,"point_in_time_facts_applied":false,"identity_policy":"frozen_csv_optional_fields_preserved"});
    let calendar=if let Some(path)=&sources.calendar{let v=read_json(path)?;let array=v.as_array().or_else(||v.get("dates").and_then(Value::as_array)).ok_or("calendar JSON must contain dates")?;let days=array.iter().map(|v|v.as_str().map(str::to_string).ok_or_else(||"invalid calendar date".into())).collect::<AnalyticsResult<Vec<_>>>()?;let known:BTreeSet<_>=days.iter().collect();for bar in grouped.values().flatten(){if !known.contains(&bar.timestamp){return Err("research bar outside supplied calendar".into());}}provenance["calendar"]=json!({"path":path.to_string_lossy(),"sha256":fingerprint(path).map_err(|e|e.to_string())?});Some(days)}else{None};
    if let Some(path)=&sources.security_master{let master=SecurityMaster::load(path).map_err(|e|e.to_string())?;let mut unknown=0;let mut conflicts=0;for bar in grouped.values().flatten(){match master.at(&bar.symbol,&bar.timestamp,&format!("{}T09:30:00+08:00",bar.timestamp)).map_err(|e|e.to_string())?{None=>unknown+=1,Some(fact)=>{if bar.raw_is_st.is_some_and(|v|v!=fact.st)||bar.raw_trading_active.is_some_and(|v|v!=(fact.active&&!fact.suspended)){conflicts+=1;}}}}if conflicts>0{return Err("frozen CSV permissions conflict with point-in-time security facts".into());}provenance["security_master"]=json!({"path":path.to_string_lossy(),"sha256":fingerprint(path).map_err(|e|e.to_string())?,"unknown_rows":unknown,"conflicting_rows":conflicts});}
    provenance["calendar_sessions"]=json!(calendar.as_ref().map(Vec::len));Ok(Inputs{grouped,sessions,metadata,first,last,provenance})
}
pub(crate) fn stress(config:&ExecutionParameters)->ExecutionParameters{let mut c=config.clone();c.commission_bps_per_side*=Decimal::TWO;c.slippage_bps_per_side*=Decimal::TWO;c.minimum_commission*=Decimal::TWO;c}
pub(crate) fn write_signals(output:&Path,signals:&[Value])->AnalyticsResult<()>{fs::create_dir_all(output).map_err(|e|e.to_string())?;let mut columns:BTreeSet<String>=["timestamp","symbol","bar_index","side","reference_price","invalidation_price","reason","trigger_timestamp","retracement","rvol","regime","target_price","minimum_reward_risk"].map(str::to_string).into_iter().collect();for row in signals{if let Some(row)=row.as_object(){columns.extend(row.keys().cloned());}}research::write_rows(&output.join("signals.csv"),signals,&columns.into_iter().collect::<Vec<_>>())}
fn signal_values(signals:&[Signal])->AnalyticsResult<Vec<Value>>{signals.iter().map(|s|crate::indexed_json::to_value(s).map_err(|e|e.to_string())).collect()}
fn period(protocol:&Value,labels:&[&str],last:&str,nested:bool,grouped:&BTreeMap<String,Vec<RuleCandle>>,each:bool)->AnalyticsResult<BTreeMap<String,(String,String)>>{let source=if nested{&protocol["periods"]}else{protocol};let mut output=BTreeMap::new();let mut previous:Option<String>=None;for label in labels{let pair=source[*label].as_array().filter(|v|v.len()==2).ok_or("research period missing")?;let start=pair[0].as_str().ok_or("period start missing")?;let end=pair[1].as_str().unwrap_or(last);crate::data::tdx::parse_date(start).and_then(|_|crate::data::tdx::parse_date(end)).map_err(|e|e.to_string())?;if start>end||end>last||previous.as_deref().is_some_and(|p|p>=start){return Err("periods must be ordered, nonoverlapping and covered".into());}let covered=|bars:&Vec<RuleCandle>|bars.iter().any(|b|start<=b.timestamp.as_str()&&b.timestamp.as_str()<=end);if if each{!grouped.values().all(covered)}else{!grouped.values().any(covered)}{return Err("period has missing security observations".into());}output.insert(label.to_string(),(start.into(),end.into()));previous=Some(end.into());}Ok(output)}
pub(crate) fn result(account:&StrategyBacktest,grouped:&BTreeMap<String,Vec<RuleCandle>>,signals:&[Value],audit:&[Value],end:&str)->AnalyticsResult<Value>{let mut output=research::build_result(account,grouped,signals,audit,None)?;let episodes=holding_drawdown::holding_drawdowns(grouped,output["orders"].as_array().ok_or("orders missing")?,Some(end),None,None)?;super::merge(&mut output["metrics"],&holding_drawdown::drawdown_metrics(&episodes));output["holding_drawdowns"]=json!(episodes);if let Some(m)=output["metrics"].as_object_mut(){m.remove("holding_drawdown_status");}Ok(output)}
/// 原因果信号保留全部热身历史；账户和挂单只在指定日期区间建立。
pub(crate) fn portfolio(input:&Inputs,signals:&[Signal],parameters:&ExecutionParameters,begin:&str,end:&str)->AnalyticsResult<Value>{portfolio_with_confirmation(input,signals,parameters,begin,end,false)}
pub(crate) fn portfolio_with_confirmation(input:&Inputs,signals:&[Signal],parameters:&ExecutionParameters,begin:&str,end:&str,n_target:bool)->AnalyticsResult<Value>{
    portfolio_values(input,&signal_values(signals)?,parameters,begin,end,&TradingDayConfig{n_target_trend_confirmation_enabled:n_target,..TradingDayConfig::lecture()})
}
pub(crate) fn portfolio_values(input:&Inputs,signals:&[Value],parameters:&ExecutionParameters,begin:&str,end:&str,trading:&TradingDayConfig)->AnalyticsResult<Value>{
    let config=system_configuration(parameters,trading.clone(),begin,end)?;
    let sessions:Vec<_>=input.sessions.iter().filter(|s|s.daily.timestamp.as_str()<=end).cloned().collect();
    let generated=system::run_system_backtest_with_signals(&sessions,config,signals,None,|_|{})?;
    let frozen:Vec<_>=signals.iter().filter(|s|s["timestamp"].as_str().is_some_and(|t|date(t)<=end)).cloned().collect();
    result(&generated.account,&input.grouped,&frozen,&generated.audit,end)
}
pub fn benchmark(grouped:&BTreeMap<String,Vec<RuleCandle>>,begin:&str,end:&str,capital:Decimal)->AnalyticsResult<Value>{if grouped.is_empty()||capital<=Decimal::ZERO{return Err("benchmark needs securities and positive capital".into());}let mut calendar=BTreeMap::<String,BTreeMap<String,&RuleCandle>>::new();for(symbol,bars)in grouped{for bar in bars{if begin<=bar.timestamp.as_str()&&bar.timestamp.as_str()<=end{calendar.entry(bar.timestamp.clone()).or_default().insert(symbol.clone(),bar);}}}let allocation=capital/Decimal::from(grouped.len()as u64);let mut cash=capital;let mut units=BTreeMap::new();let mut marks=BTreeMap::new();let mut curve=Vec::new();for(when,current)in calendar{for(symbol,bar)in current{if !units.contains_key(&symbol){units.insert(symbol.clone(),allocation/bar.open);cash-=allocation;}marks.insert(symbol,bar.close);}let value=units.iter().map(|(symbol,units)|*units*marks[symbol]).sum::<Decimal>();let equity=cash+value;curve.push(json!({"timestamp":when,"cash":float(cash)?,"market_value":float(value)?,"equity":float(equity)?,"exposure":float(value/equity)?,"positions":units.len()}));}Ok(json!({"metrics":metrics::equity_metrics(&curve,capital)?,"equity":curve,"trades":[],"orders":[],"signals":[],"audit":[],"open_positions":[],"holding_drawdowns":[],"backtest":{"source":"equal_weight_gross_fixed_basket","fees":0,"initial_capital":float(capital)?}}))}
fn publish(path:&Path,value:&Value)->AnalyticsResult<Value>{research::save_result(path,value)?;Ok(value["metrics"].clone())}
fn years(begin:&str,end:&str)->AnalyticsResult<Vec<(String,String,String)>>{let first:i32=begin.get(..4).ok_or("year missing")?.parse().map_err(|_|"invalid year")?;let last:i32=end.get(..4).ok_or("year missing")?.parse().map_err(|_|"invalid year")?;Ok((first..=last).map(|year|{let a=format!("{year}-01-01");let b=format!("{year}-12-31");(year.to_string(),a.as_str().max(begin).into(),b.as_str().min(end).into())}).collect())}
fn metric(rows:&Value,key:&str)->AnalyticsResult<f64>{number(&rows[key]).ok_or_else(||format!("metric {key} missing"))}
fn common_report(input:&Inputs,protocol:&Path,tests:Option<&Value>)->AnalyticsResult<Value>{Ok(json!({"data":input.metadata,"protocol_sha256":fingerprint(protocol).map_err(|e|e.to_string())?,"engineering_tests":tests.cloned().unwrap_or_else(||json!({"status":"not_run_by_this_command"})),"source_sha256":source_hashes(),"input_sources":input.provenance,"environment":{"runtime":"rust_native","package_version":env!("CARGO_PKG_VERSION"),"operating_system":std::env::consts::OS},"production_ready":false,"limitations":["固定输入证券范围不证明历史全市场完整性。","无分钟输入时不伪造分钟成交或完整持仓边界极值。","本入口只重放冻结数据，不代表真实券商成交、竞价队列或完整红利现金台账。"]}))}
pub fn run_research(csv:&Path,output:&Path,config:&Value,protocol_path:&Path,tests:Option<&Value>)->AnalyticsResult<Value>{
    let parameters=parameters(config)?;let input=inputs(csv,false,&RunnerSources::default())?;let protocol=read_json(protocol_path)?;let periods=period(&protocol,&["train","validation","test"],&input.last,false,&input.grouped,false)?;prepare_output(output)?;research::write_json(&output.join("protocol.json"),&protocol)?;
    let features=input.grouped.iter().map(|(symbol,bars)|Ok((symbol.clone(),baseline::compute_features(bars,&parameters)?))).collect::<AnalyticsResult<BTreeMap<_,_>>>()?;
    let qs=protocol["retracement_grid"].as_array().ok_or("retracement grid missing")?;let rs=protocol["rvol_grid"].as_array().ok_or("rvol grid missing")?;if qs.is_empty()||rs.is_empty()||qs.len().saturating_mul(rs.len())>10000{return Err("invalid training grid size".into());}let minimum=metric(&protocol,"minimum_training_trades")?;
    let mut grid=Vec::new();let mut winner:Option<(f64,ExecutionParameters)>=None;let(train_begin,train_end)=&periods["train"];
    for q in qs{for rvol in rs{let mut candidate=parameters.clone();candidate.max_retracement=dec(q).ok_or("invalid retracement grid")?;candidate.min_rvol=dec(rvol).ok_or("invalid rvol grid")?;candidate.validate()?;let mut signals=Vec::new();for f in features.values(){signals.extend(baseline::generate_signals(f,&candidate)?);}signals.sort_by(|a,b|(&a.timestamp,&a.symbol,&a.side).cmp(&(&b.timestamp,&b.symbol,&b.side)));let result=portfolio(&input,&signals,&candidate,train_begin,train_end)?;let m=&result["metrics"];let sharpe=number(&m["sharpe"]);let eligible=metric(m,"trades")?>=minimum&&sharpe.is_some();if eligible{let value=sharpe.ok_or("eligible Sharpe missing")?;if winner.as_ref().is_none_or(|(old,_)|value>*old){winner=Some((value,candidate.clone()));}}grid.push(json!({"max_retracement":candidate.max_retracement,"min_rvol":candidate.min_rvol,"eligible":eligible,"metrics":m}));}}
    research::write_json(&output.join("training_grid.json"),&json!(grid))?;let selected=winner.as_ref().map(|(_,p)|p.clone()).unwrap_or_else(||parameters.clone());let mut no_volume=parameters.clone();no_volume.min_rvol=Decimal::ZERO;let mut no_regime=parameters.clone();no_regime.require_non_bearish_regime=false;
    let strategies=[("wave_default",parameters.clone(),false),("plain_breakout",parameters.clone(),true),("no_volume",no_volume,false),("no_regime",no_regime,false),("train_selected",selected.clone(),false)];let mut results=BTreeMap::<String,Value>::new();let mut curves=BTreeMap::<String,Vec<Value>>::new();let mut signal_sets=BTreeMap::new();
    for(name,config,plain)in strategies{let signals=baseline::make_signals(&input.grouped,&config,plain)?;write_signals(&output.join(name),&signal_values(&signals)?)?;let mut rows=json!({});for(label,(begin,end))in &periods{let r=portfolio(&input,&signals,&config,begin,end)?;rows[label]=publish(&output.join(name).join(label),&r)?;if label=="test"{curves.insert(name.into(),r["equity"].as_array().ok_or("equity missing")?.clone());}}results.insert(name.into(),rows);signal_sets.insert(name.to_string(),signals);}
    let stress=stress(&selected);let(begin,end)=&periods["test"];let stressed=portfolio(&input,&signal_sets["train_selected"],&stress,begin,end)?;results.insert("selected_cost_2x".into(),json!({"test":publish(&output.join("selected_cost_2x/test"),&stressed)?}));let mut benchmark_metrics=json!({});for(label,(begin,end))in &periods{let b=benchmark(&input.grouped,begin,end,parameters.initial_capital)?;benchmark_metrics[label]=publish(&output.join("equal_weight_gross").join(label),&b)?;if label=="test"{curves.insert("equal_weight_gross".into(),b["equity"].as_array().ok_or("benchmark curve missing")?.clone());}}results.insert("equal_weight_gross".into(),benchmark_metrics);
    let mut annual=json!({});for(year,begin,end)in years(begin,end)?{let r=portfolio(&input,&signal_sets["train_selected"],&selected,&begin,&end)?;annual[&year]=publish(&output.join("annual_test").join(&year),&r)?;}
    let tested=&results["train_selected"]["test"];let threshold=&protocol["research_gate"];let min_sharpe=metric(threshold,"minimum_test_sharpe")?;let checks=json!({"validation_positive":metric(&results["train_selected"]["validation"],"total_return")?>0.0,"test_positive":metric(tested,"total_return")?>0.0,"test_trade_count":metric(tested,"trades")?>=metric(threshold,"minimum_test_trades")?,"test_sharpe":number(&tested["sharpe"]).is_some_and(|v|v>=min_sharpe),"test_drawdown":metric(tested,"max_drawdown")?>=-metric(threshold,"maximum_test_drawdown")?,"cost_stress_positive":metric(&stressed["metrics"],"total_return")?>0.0});
    let mut report=common_report(&input,protocol_path,tests)?;let quality=quality::audit_data(csv)?;research::write_json(&output.join("data_quality.json"),&quality)?;super::merge(&mut report,&json!({"protocol":protocol,"periods":periods,"base_config":parameters,"selected_config":selected,"stress_config":stress,"selection_fallback":winner.is_none(),"results":results,"annual_test_diagnostics":annual,"data_quality":quality,"bootstrap":evidence_statistics::block_bootstrap(&curves["train_selected"],float(parameters.initial_capital)?,20260908)?,"diagnostics":{"regime_filter_redundant":signal_sets["wave_default"]==signal_sets["no_regime"]},"research_gate":{"passed":checks.as_object().is_some_and(|m|m.values().all(|v|v==true)),"checks":checks},"test_curves":curves}));research::report_files(output,&report)?;Ok(report)
}
pub fn run_notion(csv:&Path,notes:&Path,output:&Path,protocol_path:&Path,config:&Value,tests:Option<&Value>)->AnalyticsResult<Value>{
    let config=parameters(config)?;let input=inputs(csv,false,&RunnerSources::default())?;let protocol=read_json(protocol_path)?;let periods=period(&protocol,&["train","validation","diagnostic"],&input.last,false,&input.grouped,true)?;if protocol["future_start"].as_str().is_none_or(|start|input.last.as_str()>=start){return Err("future data mixed into historical run; use a separately frozen forward evaluation".into());}let inventory=notion::inventory_notes(notes)?;let variants=protocol["variants"].as_object().filter(|v|!v.is_empty()).ok_or("Notion variants missing")?;let mut settings=BTreeMap::<String,StructureConfig>::new();for(name,value)in variants{safe_name(name)?;let setting:StructureConfig=crate::indexed_json::from_value(value.clone()).map_err(|e|e.to_string())?;setting.validate()?;settings.insert(name.clone(),setting);}prepare_output(output)?;research::write_json(&output.join("notes_inventory.json"),&inventory)?;research::write_json(&output.join("protocol.json"),&protocol)?;research::write_json(&output.join("resolved_variants.json"),&json!(settings))?;
    let mut signal_sets=BTreeMap::from([("legacy_v1".into(),baseline::make_signals(&input.grouped,&config,false)?),("plain_breakout".into(),baseline::make_signals(&input.grouped,&config,true)?)]);for(name,setting)in &settings{let mut signals=Vec::new();for bars in input.grouped.values(){signals.extend(baseline::structural_signals(bars,setting)?);}signals.sort_by(|a,b|(&a.timestamp,&a.symbol,&a.side).cmp(&(&b.timestamp,&b.symbol,&b.side)));signal_sets.insert(name.clone(),signals);}
    let stress=stress(&config);let mut results=BTreeMap::new();let mut intervals=json!({});let mut counts=json!({});let mut yearly=json!({});let(begin,end)=&periods["diagnostic"];
    for(name,signals)in &signal_sets{write_signals(&output.join(name),&signal_values(signals)?)?;counts[name]=json!(signals.len());let mut rows=json!({});for(label,(begin,end))in &periods{let r=portfolio(&input,signals,&config,begin,end)?;rows[label]=publish(&output.join(name).join(label),&r)?;if label=="diagnostic"{intervals[name]=evidence_statistics::block_bootstrap(r["equity"].as_array().ok_or("equity missing")?,float(config.initial_capital)?,20260908)?;}}let r=portfolio(&input,signals,&stress,begin,end)?;rows["cost_2x"]=publish(&output.join(name).join("cost_2x"),&r)?;let mut annual=json!({});for(year,begin,end)in years(begin,end)?{let r=portfolio(&input,signals,&config,&begin,&end)?;annual[&year]=publish(&output.join(name).join("annual_reset").join(&year),&r)?;}yearly[name]=annual;results.insert(name.clone(),rows);}
    let bench=benchmark(&input.grouped,begin,end,config.initial_capital)?;publish(&output.join("equal_weight_gross/diagnostic"),&bench)?;let mut report=common_report(&input,protocol_path,tests)?;super::merge(&mut report,&json!({"base_config":config,"stress_config":stress,"protocol":protocol,"variants":settings,"signal_counts":counts,"annual_reset_diagnostics":yearly,"bootstrap":intervals,"equal_weight_gross":bench["metrics"]}));notion::assemble_report(report,&settings.keys().cloned().collect::<Vec<_>>(),&results,&inventory,Some(output))
}

fn system_configuration(parameters:&ExecutionParameters,trading:TradingDayConfig,begin:&str,end:&str)->AnalyticsResult<SystemConfig>{
    let profile=StrategyProfile{strategy:trading.clone(),parameters:json!(trading),scenarios:BTreeMap::from([("research".into(),json!({"execution":parameters}))]),profile_version:"frozen_system_research".into(),definition:json!({}),extra:BTreeMap::new()};let(execution,holding)=profiles::execution_configuration(&profile,"research")?;
    let analyzer=AnalyzerConfig{n_target_trend_confirmation_enabled:trading.n_target_trend_confirmation_enabled,trading,..AnalyzerConfig::default()};Ok(SystemConfig{analyzer,execution,holding,parameters:parameters.clone(),trading_start:Some(begin.into()),trading_end:Some(end.into())})
}
pub(crate) fn system_result(input:&Inputs,parameters:&ExecutionParameters,trading:&TradingDayConfig,begin:&str,end:&str)->AnalyticsResult<(Value,system::SystemBacktest)>{
    let config=system_configuration(parameters,trading.clone(),begin,end)?;let sessions:Vec<_>=input.sessions.iter().filter(|s|s.daily.timestamp.as_str()<=end).cloned().collect();let generated=system::run_system_backtest(&sessions,config,None,|_|{})?;let output=result(&generated.account,&input.grouped,&generated.signals,&generated.audit,end)?;Ok((output,generated))
}
pub(crate) fn coverage(generated:&system::SystemBacktest)->Value{let mut rows=BTreeMap::<String,BTreeMap<String,usize>>::new();for symbol in generated.bars.keys(){rows.entry(symbol.clone()).or_default();}for event in &generated.audit{if let(Some(symbol),Some(kind))=(event["symbol"].as_str(),event["event"].as_str()){*rows.entry(symbol.into()).or_default().entry(kind.into()).or_default()+=1;}}for signal in &generated.signals{if signal["side"]=="LONG"{if let Some(symbol)=signal["symbol"].as_str(){*rows.entry(symbol.into()).or_default().entry("long_signals".into()).or_default()+=1;}}}json!(rows)}
pub fn run_system_research(csv:&Path,output:&Path,protocol:&Path,tests:&Value)->AnalyticsResult<Value>{run_system_research_with_sources(csv,output,protocol,tests,&RunnerSources::default())}
pub fn run_system_research_with_sources(csv:&Path,output:&Path,protocol_path:&Path,tests:&Value,sources:&RunnerSources)->AnalyticsResult<Value>{
    if tests["status"]!="passed"{return Err("engineering test gate must pass before fixed system research".into());}let input=inputs(csv,true,sources)?;let protocol=read_json(protocol_path)?;system_research::validate_protocol(&input.grouped,&protocol)?;let periods=period(&protocol,&["train","validation","diagnostic"],&input.last,true,&input.grouped,true)?;let execution=parameters(&protocol["execution"])?;let variants=protocol["variants"].as_object().filter(|v|!v.is_empty()).ok_or("system variants missing")?;let mut configs=BTreeMap::<String,TradingDayConfig>::new();
    for(name,changes)in variants{safe_name(name)?;let mut config=json!({"entry_policy":"legacy_n_continuation","preflight_reward_risk":false,"squeeze_pullback_entries":false});if !protocol["strategy"].is_object()||!changes.is_object(){return Err("system strategy and variant changes must be objects".into());}super::merge(&mut config,&protocol["strategy"]);super::merge(&mut config,changes);let config:TradingDayConfig=crate::indexed_json::from_value(config).map_err(|e|e.to_string())?;config.validate()?;configs.insert(name.clone(),config);}
    prepare_output(output)?;research::write_json(&output.join("protocol.json"),&protocol)?;research::write_json(&output.join("execution.json"),&json!(execution))?;research::write_json(&output.join("source_sha256.json"),&source_hashes())?;let mut results=BTreeMap::new();let mut counts=json!({});let mut diagnostics=json!({});let mut unavailable=BTreeSet::new();let stress=stress(&execution);
    for(name,config)in &configs{let mut rows=json!({});let mut diag=json!({});let mut final_generated=None;for label in ["train","validation","diagnostic"]{let(begin,end)=&periods[label];let(r,generated)=system_result(&input,&execution,config,begin,end)?;rows[label]=publish(&output.join(name).join(label),&r)?;diag[label]=r["backtest"]["diagnostics"].clone();unavailable.extend(generated.unavailable_rules.iter().cloned());final_generated=Some(generated);}let(begin,end)=&periods["diagnostic"];let(r,_)=system_result(&input,&stress,config,begin,end)?;rows["cost_2x"]=publish(&output.join(name).join("cost_2x"),&r)?;diag["cost_2x"]=r["backtest"]["diagnostics"].clone();let generated=final_generated.ok_or("system periods missing")?;write_signals(&output.join(name),&generated.signals)?;research::write_json(&output.join(name).join("event_audit.json"),&json!(generated.audit))?;let count=coverage(&generated);research::write_json(&output.join(name).join("coverage.json"),&count)?;counts[name]=count;results.insert(name.clone(),rows);diagnostics[name]=diag;}
    let plain=baseline::make_signals(&input.grouped,&execution,true)?;write_signals(&output.join("plain_breakout"),&signal_values(&plain)?)?;for name in ["plain_breakout","equal_weight_gross"]{let mut rows=json!({});for(label,(begin,end))in &periods{let result=if name=="plain_breakout"{portfolio(&input,&plain,&execution,begin,end)?}else{benchmark(&input.grouped,begin,end,execution.initial_capital)?};rows[label]=publish(&output.join(name).join(label),&result)?;}results.insert(name.into(),rows);}
    let mut annual=json!({});for name in ["strict_full","proxy_full"]{let Some(config)=configs.get(name)else{continue;};let mut rows=json!({});if input.last.as_str()>="2024-01-01"{for(year,begin,end)in years("2024-01-01",&input.last)?{let(r,_)=system_result(&input,&execution,config,&begin,&end)?;rows[&year]=publish(&output.join(name).join("annual").join(&year),&r)?;}}annual[name]=rows;}
    let quality=quality::audit_data(csv)?;research::write_json(&output.join("data_quality.json"),&quality)?;research::write_json(&output.join("execution_diagnostics.json"),&diagnostics)?;let mut report=common_report(&input,protocol_path,Some(tests))?;super::merge(&mut report,&json!({"strategy_configs":configs,"execution":execution,"coverage":counts,"annual":annual,"data_quality":quality,"execution_diagnostics":diagnostics,"unavailable":unavailable,"signal_audit_through":periods["diagnostic"].1}));system_research::assemble_report(report,&protocol,&results,Some(output))
}
pub fn run_backtest(csv:&Path,output:&Path,config:&Value)->AnalyticsResult<Value>{
    let config=parameters(config)?;let input=inputs(csv,false,&RunnerSources::default())?;let signals=baseline::make_signals(&input.grouped,&config,false)?;
    let result=portfolio(&input,&signals,&config,&input.first,&input.last)?;research::save_result_with_inputs(output,&result,&[csv,&csv.with_extension("metadata.json")])?;
    let mut report=common_report(&input,csv,None)?;if let Some(map)=report.as_object_mut(){map.remove("protocol_sha256");}
    super::merge(&mut report,&json!({"config":config,"metrics":result["metrics"],"signal_count":signals.len(),"results":result}));
    research::report_files(output,&report)?;Ok(report)
}
